#[derive(Clone,Copy)]enum Mode{Ack,Zero,Unknown,Partial,LocalNotSent,FirstCall}
struct Clock(Arc<AtomicU64>);impl sdk::Clock for Clock{fn now_ms(&self)->u64{self.0.load(Ordering::SeqCst)}fn sleep_ms(&mut self,n:u64)->sdk::Result<()>{self.0.fetch_add(n,Ordering::SeqCst);Ok(())}}
fn error(code:&str)->TransportError{TransportError{code:code.into(),status:None,may_have_executed:false,retry_after_ms:0,order_id:None,api_code:None}}
struct GuardState{ready:Option<Prepared>,owned:BTreeSet<String>,deny_network:bool}
struct Guard{state:Arc<Mutex<GuardState>>,scope:Scope,cutoff:u64}
impl sdk::Authority for Guard{
 fn can_read(&self,s:&Scope)->bool{fixture::hash(s)==fixture::hash(&self.scope)}
 fn owns_order(&self,id:&str)->bool{self.state.lock().unwrap().owned.contains(id)}
 fn authorize(&self,s:&Scope,r:&RequestSpec,p:&Permit,network:bool,now:u64)->sdk::Result<()>{if fixture::hash(s)!=fixture::hash(&self.scope){return Err(error("TEST_SCOPE"))}let state=self.state.lock().unwrap();let ready=state.ready.as_ref().ok_or_else(||error("TEST_NO_READY"))?;ready.authorize(r,p,now,&state.owned,self.cutoff).map_err(|_|error("TEST_PHYSICAL_FACTS"))?;if network&&state.deny_network{return Err(error("TEST_NETWORK_DENIED"))}Ok(())}
}
struct Server{url:String,stop:Arc<AtomicBool>,thread:Option<thread::JoinHandle<()>>,posts:Arc<AtomicUsize>,gets:Arc<AtomicUsize>}
impl Drop for Server{fn drop(&mut self){self.stop.store(true,Ordering::SeqCst);if let Some(h)=self.thread.take(){h.join().unwrap();}}}
fn request(stream:&mut TcpStream)->(String,Value){stream.set_read_timeout(Some(Duration::from_secs(2))).unwrap();let mut bytes=Vec::new();let end=loop{let mut b=[0;1024];let n=stream.read(&mut b).unwrap();assert!(n>0);bytes.extend_from_slice(&b[..n]);assert!(bytes.len()<1024*1024);if let Some(i)=bytes.windows(4).position(|w|w==b"\r\n\r\n"){break i+4}};let headers=String::from_utf8(bytes[..end].to_vec()).unwrap();let len=headers.lines().find_map(|l|l.to_ascii_lowercase().strip_prefix("content-length:").map(|n|n.trim().parse::<usize>().unwrap())).unwrap_or(0);while bytes.len()<end+len{let mut b=[0;4096];let n=stream.read(&mut b).unwrap();assert!(n>0);bytes.extend_from_slice(&b[..n]);}let line=headers.lines().next().unwrap().to_owned();let body=if len==0{Value::Null}else{serde_json::from_slice(&bytes[end..end+len]).unwrap()};(line,body)}
impl Server{
 fn new(mode:Mode,clock:Arc<AtomicU64>)->Self{let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let url=format!("http://{}/api/v1",listener.local_addr().unwrap());let stop=Arc::new(AtomicBool::new(false));let posts=Arc::new(AtomicUsize::new(0));let gets=Arc::new(AtomicUsize::new(0));let(s,p,g)=(stop.clone(),posts.clone(),gets.clone());let h=thread::spawn(move||{let mut legs=Vec::<Value>::new();let mut executed=NOW+3000;while !s.load(Ordering::SeqCst){let(mut stream,_)=match listener.accept(){Ok(v)=>v,Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{thread::sleep(Duration::from_millis(1));continue},Err(e)=>panic!("{e}")};let(line,body)=request(&mut stream);let mut status=200;let response=if line.starts_with("POST "){p.fetch_add(1,Ordering::SeqCst);legs=body["legs"].as_array().unwrap().clone();executed=clock.load(Ordering::SeqCst);if matches!(mode,Mode::Zero){status=429;json!({"error":{"code":"RATE_LIMITED","message":"fixture"}})}else if matches!(mode,Mode::Unknown){json!({"results":[]})}else{json!({"results":legs.iter().enumerate().map(|(i,l)|{let q=l["quantity"].as_i64().unwrap();let notional=sdk::decimal_units(&l["price"].to_string()).unwrap()*q as i128;json!({"index":i,"data":{"orderId":(9001+i).to_string(),"exchangeId":l["exchangeId"],"side":l["side"],"action":l["action"],"quantity":q,"quantityTraded":if l["side"]=="no"{-q}else{q},"remainingQuantity":0,"price":l["price"],"fillPrice":l["price"],"totalCost":serde_json::from_str::<Value>(&moloch_replay::money(notional)).unwrap(),"open":false,"all":null,"terminalReasonCode":null}})}).collect::<Vec<_>>()})}}else{g.fetch_add(1,Ordering::SeqCst);let path=line.split_whitespace().nth(1).unwrap().split('?').next().unwrap();let tape=path.ends_with("/fills");let id=path.trim_end_matches("/fills").rsplit('/').next().unwrap();let index=id.parse::<usize>().unwrap()-9001;let l=&legs[index];let q=l["quantity"].as_i64().unwrap();let n=if matches!(mode,Mode::Partial)&&index==0{q/2}else{q};let signed=if l["side"]=="no"{-n}else{n};if tape{json!({"orderId":id,"exchangeId":l["exchangeId"],"tournamentId":T,"totalQuantityFilled":signed,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null},"data":[{"id":(8001+index).to_string(),"quantity":signed,"side":l["side"],"price":l["price"],"filledAt":iso(executed)}]})}else{json!({"id":id,"exchangeId":l["exchangeId"],"tournamentId":T,"side":l["side"],"action":l["action"],"priceLimit":l["price"],"quantity":q,"quantityFilled":n,"createdAt":iso(executed),"expirationDate":null,"open":false,"terminalReasonCode":null})}};let bytes=serde_json::to_vec(&response).unwrap();let header=format!("HTTP/1.1 {status} fixture\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",bytes.len());stream.write_all(header.as_bytes()).unwrap();stream.write_all(&bytes).unwrap();}});Self{url,stop,thread:Some(h),posts,gets}}
}
struct Wire{transport:sdk::Transport,state:Arc<Mutex<GuardState>>,clock:Arc<AtomicU64>,ordinary:DispatchLog,activation:moloch_live_runtime::authority::Activation,dir:PathBuf,server:Server,calls:usize}
impl Wire{
 fn new(f:&F,mode:Mode)->Self{use std::os::unix::fs::PermissionsExt;let clock=Arc::new(AtomicU64::new(NOW));let server=Server::new(mode,clock.clone());let dir=f.root.join("prob-worker-evidence");std::fs::create_dir_all(&dir).unwrap();let credentials=f.root.join("prob-worker-fixture-credentials");std::fs::create_dir_all(&credentials).unwrap();std::fs::set_permissions(&credentials,std::fs::Permissions::from_mode(0o700)).unwrap();let file=credentials.join("dummy");std::fs::write(&file,b"ace_fixture_only_never_real_000000").unwrap();std::fs::set_permissions(&file,std::fs::Permissions::from_mode(0o600)).unwrap();let provider:Box<dyn sdk::CredentialProvider>=if matches!(mode,Mode::FirstCall){Box::new(sdk::DisabledCredentials)}else{Box::new(sdk::credentials::UnixFileCredentials::approved_file(file).unwrap())};let state=Arc::new(Mutex::new(GuardState{ready:None,owned:BTreeSet::new(),deny_network:matches!(mode,Mode::LocalNotSent)}));let activation=moloch_live_runtime::authority::Activation{run_id:"surface-fixture".into(),entry_until_ms:NOW+600000,maximum_committed:"100.000000".into(),maximum_market_cost:"100.000000".into(),maximum_quantity:100,tournament_id:T.into(),tournament_slug:"cup".into(),binary_sha256:"a".repeat(64)};let transport=sdk::Transport::new_for_mock(sdk::Config{queue_dir:f.root.join("prob-worker-actual-queue"),account_scope:"prob-fixture-account".into(),scope:f.scope.clone(),maximum_pages:4,writes_enabled:true},provider,Box::new(Clock(clock.clone())),Box::new(Guard{state:state.clone(),scope:f.scope.clone(),cutoff:activation.entry_until_ms}),server.url.clone()).unwrap();let ordinary=DispatchLog::open(&f.root.join("worker-ordinary.ndjson")).unwrap();Self{transport,state,clock,ordinary,activation,dir,server,calls:0}}
 fn time(&self,t:u64){self.clock.store(t,Ordering::SeqCst)}
}
impl base::Backend for Wire{
 fn now_ms(&self)->u64{self.clock.load(Ordering::SeqCst)}fn scope(&self)->&Scope{self.transport.scope()}fn account_scope(&self)->&str{self.transport.account_scope()}fn evidence_directory(&self)->&Path{&self.dir}
 fn quiet(&self)->feedback::Result<()>{self.ordinary.require_resolved_attempts()?;self.transport.package_queue_quiet()?;Ok(())}fn lookup(&self,intent:&str)->feedback::Result<BindingLookup>{Ok(self.transport.admission_lookup_intent(intent)?)}
 fn prepare(&mut self,_:&Session,_:&moloch_live_runtime::package_admission::Admission,_:Permit,_:PackageSnapshotSet)->feedback::Result<()>{Err("LEGACY_PREPARE_FORBIDDEN".into())}fn clear_ready(&mut self){self.state.lock().unwrap().ready=None}
 fn send(&mut self,_:multi_leg::Basket,_:Permit)->sdk::Result<multi_leg::Outcome>{panic!("legacy SDK send forbidden")}
 fn take_not_sent(&mut self)->feedback::Result<VerifiedNotSent>{Ok(VerifiedNotSent::from_sdk(self.transport.take_local_not_sent_proof()?))}fn retained_not_sent(&mut self,b:&ImmutableBinding,r:&str,min:u64)->feedback::Result<VerifiedNotSent>{Ok(VerifiedNotSent::from_sdk(self.transport.verify_retained_local_not_sent(b,r,min)?))}
 fn take_first_call_not_sent(&mut self)->feedback::Result<sdk::multi_leg_first_call::Proof>{Ok(self.transport.take_first_call_no_http_proof()?)}fn retained_first_call_not_sent(&mut self,b:&ImmutableBinding,r:&str)->feedback::Result<sdk::multi_leg_first_call::Proof>{Ok(self.transport.verify_retained_first_call_no_http(b,r)?)}
 fn bind_owned(&mut self,id:&str){self.state.lock().unwrap().owned.insert(id.into());}fn read(&mut self,e:Endpoint)->feedback::Result<Receipt>{Ok(self.transport.request(e)?)}
}
impl worker::Backend for Wire{
 fn ordinary_dispatch(&self)->&DispatchLog{&self.ordinary}
 fn prepare_probabilistic(&mut self,bank:&Session,p:&prob::Plan,r:&prob::Reservation,b:&wire::Basket,permit:Permit,facts:PackageSnapshotSet)->feedback::Result<()>{let ready=Prepared::new_probabilistic(bank,&self.activation,self.scope(),p,r,b,permit,facts,self.now_ms(),self.activation.entry_until_ms)?;self.state.lock().unwrap().ready=Some(ready);Ok(())}
 fn send_portfolio(&mut self,b:wire::Basket,p:Permit)->sdk::Result<wire::Outcome>{self.calls+=1;self.transport.place_portfolio_all_or_none(b,p)}
}
fn setup(mode:Mode)->(F,Wire,PackageDispatchLog){let mut f=F::with_tournament(T);fixture::qualify(&mut f);let w=Wire::new(&f,mode);let log=PackageDispatchLog::open(&f.root.join("prob-worker-original-dispatch")).unwrap();(f,w,log)}
fn stage(f:&mut F,w:&Wire,l:&mut PackageDispatchLog)->worker::Staged{let s=f.bound(NOW).unwrap();let c=fixture::semantics(f,&s);let p=fixture::policy(f);let plan=prob::optimize(&f.bank,&w.ordinary,&f.scope,&s,&c,&p,NOW).unwrap().unwrap();worker::stage(&mut f.bank,l,w,plan,&s,&c,&p,&w.activation).unwrap()}
fn reopen(f:&mut F){let policy=f.bank.engine().policy().clone();let seed=f.bank.live_account_seed().unwrap().clone();let replacement=Session::open_live(&f.root.join("restart-placeholder"),&policy,&seed).unwrap();let old=std::mem::replace(&mut f.bank,replacement);drop(old);let restored=Session::open_live(&f.root,&policy,&seed).unwrap();let placeholder=std::mem::replace(&mut f.bank,restored);drop(placeholder);}
#[test]fn actual_sdk_ack_is_not_fill_then_full_original_tapes_complete_without_second_post(){let(mut f,mut w,mut l)=setup(Mode::Ack);let staged=stage(&mut f,&w,&mut l);let facts=fixture::facts(&f,NOW+3000);w.time(NOW+3000);assert_eq!(worker::submit_once(&mut f.bank,&mut l,&mut w,staged,facts).unwrap(),worker::SendResult::Acknowledged);assert!(f.bank.engine().fills().is_empty());assert_eq!(w.server.posts.load(Ordering::SeqCst),1);let original=f.bank.engine().report().unwrap();let legacy=base::recover(&mut f.bank,&mut l,&mut w).unwrap();assert_eq!(legacy.fill_events,0);assert_eq!(f.bank.engine().report().unwrap(),original);let r=worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert_eq!(r.completed_packages,1);assert_eq!(r.fill_events,2);assert_eq!(w.server.gets.load(Ordering::SeqCst),4);assert_eq!(w.calls,1);assert!(!worker::recover(&mut f.bank,&mut l,&mut w).unwrap().blocks_new_submissions);assert_eq!(w.server.posts.load(Ordering::SeqCst),1);}
#[test]fn sdk_definitive_zero_and_positive_local_no_send_release_without_profit(){for mode in [Mode::Zero,Mode::LocalNotSent,Mode::FirstCall]{let(mut f,mut w,mut l)=setup(mode);let staged=stage(&mut f,&w,&mut l);let facts=fixture::facts(&f,NOW+3000);w.time(NOW+3000);let result=worker::submit_once(&mut f.bank,&mut l,&mut w,staged,facts).unwrap();assert_eq!(result,if matches!(mode,Mode::Zero){worker::SendResult::DefinitiveZero}else{worker::SendResult::LocalNotSent});assert_eq!(f.bank.engine().wallet.reserved().unwrap(),0);assert!(f.bank.engine().fills().is_empty());assert_eq!(f.bank.engine().report().unwrap()["cash"],"100.000000");assert!(!worker::recover(&mut f.bank,&mut l,&mut w).unwrap().blocks_new_submissions);assert_eq!(w.calls,1);assert_eq!(w.server.posts.load(Ordering::SeqCst),usize::from(matches!(mode,Mode::Zero)));}}
#[test]fn ambiguous_real_sdk_response_keeps_full_funding_and_never_retries(){let(mut f,mut w,mut l)=setup(Mode::Unknown);let staged=stage(&mut f,&w,&mut l);let facts=fixture::facts(&f,NOW+3000);w.time(NOW+3000);assert_eq!(worker::submit_once(&mut f.bank,&mut l,&mut w,staged,facts).unwrap(),worker::SendResult::Unknown);assert!(l.unresolved());assert_eq!(f.bank.engine().wallet.reserved().unwrap(),3_600_000);assert!(worker::recover(&mut f.bank,&mut l,&mut w).unwrap().blocks_new_submissions);assert_eq!(w.server.posts.load(Ordering::SeqCst),1);assert_eq!(w.calls,1);}
#[test]fn original_complete_partial_fill_tapes_credit_only_real_quantity_and_stay_blocked(){let(mut f,mut w,mut l)=setup(Mode::Partial);let staged=stage(&mut f,&w,&mut l);let facts=fixture::facts(&f,NOW+3000);w.time(NOW+3000);worker::submit_once(&mut f.bank,&mut l,&mut w,staged,facts).unwrap();let r=worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert_eq!(r.completed_packages,0);assert!(r.blocks_new_submissions);assert_eq!(f.bank.engine().wallet.quantity("104",moloch_replay::Side::Yes),2);assert_eq!(f.bank.engine().wallet.quantity("105",moloch_replay::Side::Yes),5);assert_eq!(w.server.posts.load(Ordering::SeqCst),1);}
#[test]fn restart_intent_never_resumes_send_and_original_journal_fence_releases(){let(mut f,mut w,mut l)=setup(Mode::Ack);let _lost=stage(&mut f,&w,&mut l);let path=f.root.join("prob-worker-original-dispatch");drop(l);let mut l=PackageDispatchLog::open(&path).unwrap();let before=f.bank.engine().wallet.cash;let r=worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert_eq!(r.abandoned_unattempted,1);assert_eq!(f.bank.engine().wallet.cash,before);assert_eq!(f.bank.engine().wallet.reserved().unwrap(),0);assert_eq!(w.calls,0);assert_eq!(w.server.posts.load(Ordering::SeqCst),0);}
#[test]fn stale_or_changed_physical_facts_do_not_issue_sdk_request(){for change in ["cash","rule","future"]{let(mut f,mut w,mut l)=setup(Mode::Ack);let staged=stage(&mut f,&w,&mut l);let mut facts=fixture::facts(&f,NOW+3000);match change{"cash"=>facts.cash_balance.data["balance"]=json!(99),"rule"=>facts.components.get_mut("104").unwrap().contract.data["root"]["settled_with"]=json!("changed"),_=>facts.cash_balance.received_at=iso(NOW+99999)}w.time(NOW+3000);assert_eq!(worker::submit_once(&mut f.bank,&mut l,&mut w,staged,facts).unwrap(),worker::SendResult::NeverAttempted);assert_eq!(w.calls,0);assert_eq!(f.bank.engine().wallet.reserved().unwrap(),0);assert_eq!(w.server.posts.load(Ordering::SeqCst),0);}}
#[test]fn original_ack_journal_before_native_ack_and_partial_mapping_restart_idempotently(){for partially_mapped in [false,true]{let(mut f,mut w,mut l)=setup(Mode::Ack);let staged=stage(&mut f,&w,&mut l);let id=staged.package_id().to_owned();let spec=wire::request_spec(staged.basket(),&f.scope,staged.permit()).unwrap();w.time(NOW+3000);let p=f.bank.engine().package_records()[0].clone();let hashes=f.bank.engine().live_package_books().iter().filter(|r|staged.basket().legs.iter().any(|l|r["exchangeId"]==l.exchange_id)).map(|r|(r["exchangeId"].as_str().unwrap().to_owned(),json!(fixture::hash(r)))).collect::<serde_json::Map<_,_>>();f.bank.accept("crash-attempt",1,&json!({"type":"probabilistic_portfolio_attempt_v1","source":"moloch_live_dispatcher","receivedAt":iso(w.now_ms()),"processedAt":iso(w.now_ms()),"packageId":id,"proofHash":p["proofHash"],"bankScope":p["bankScope"],"requestHash":fixture::hash(&spec),"idempotencyKey":staged.basket().idempotency_key,"bookHashes":hashes})).unwrap();worker::Backend::prepare_probabilistic(&mut w,&f.bank,staged.plan(),staged.reservation(),staged.basket(),staged.permit().clone(),fixture::facts(&f,NOW+3000)).unwrap();let _attempt=l.attempt(&id,&iso(w.now_ms())).unwrap();let outcome=worker::Backend::send_portfolio(&mut w,staged.basket().clone(),staged.permit().clone()).unwrap();let receipt=match outcome{wire::Outcome::FullFillReported{receipt,..}=>receipt,_=>panic!("expected genuine SDK ACK")};l.acknowledged(&id,&receipt,&iso(w.now_ms())).unwrap();if partially_mapped{let p=f.bank.engine().package_records()[0].clone();let event=moloch_live_runtime::package_portfolio_feedback::acknowledgment(&f.bank,&p,staged.basket(),&f.scope,staged.permit(),&receipt,&iso(w.now_ms())).unwrap();f.bank.accept("crash-one-ack",1,&event["acknowledgments"][0]).unwrap();}drop(staged);w.clear_ready();let report=f.bank.engine().report().unwrap();drop(l);reopen(&mut f);assert_eq!(f.bank.engine().report().unwrap(),report);let mut l=PackageDispatchLog::open(&f.root.join("prob-worker-original-dispatch")).unwrap();let r=worker::recover(&mut f.bank,&mut l,&mut w).unwrap();assert_eq!(r.completed_packages,1);assert_eq!(f.bank.engine().fills().len(),2);assert_eq!(w.server.posts.load(Ordering::SeqCst),1);assert_eq!(w.calls,1);}}
